"""Consistency tests for benchmark_data/index.yaml and index.csv.

The index files are generated by scripts/generate_dataset.py; these tests
guarantee they stay in sync with the on-disk task YAML files.
"""
from __future__ import annotations

import csv
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parent.parent
DATA_ROOT = ROOT / "benchmark_data"
INDEX_FIELDS = [
    "id", "layer", "category", "domain", "subdomain", "difficulty",
    "estimated_time_min", "primary_skill", "file_path",
]


def load_problems() -> dict[str, dict]:
    problems = {}
    for path in sorted(DATA_ROOT.rglob("*.yaml")):
        if path.name == "index.yaml":
            continue
        data = yaml.safe_load(path.read_text(encoding="utf-8"))
        problems[data["id"]] = {"path": path, "data": data}
    return problems


def load_index_yaml() -> dict:
    return yaml.safe_load((DATA_ROOT / "index.yaml").read_text(encoding="utf-8"))


def test_index_yaml_ids_match_disk():
    problems = load_problems()
    index = load_index_yaml()
    index_ids = {item["id"] for item in index["items"]}
    assert index_ids == set(problems), (
        "index.yaml out of sync with on-disk YAML files; "
        "run scripts/generate_dataset.py"
    )
    assert index["total_count"] == len(index["items"])
    assert len(index["items"]) > 0


def test_index_yaml_ids_unique_and_sorted():
    items = load_index_yaml()["items"]
    ids = [item["id"] for item in items]
    assert len(ids) == len(set(ids))
    assert ids == sorted(ids)


def test_index_yaml_rows_match_problem_fields():
    problems = load_problems()
    for item in load_index_yaml()["items"]:
        data = problems[item["id"]]["data"]
        for field in ("layer", "category", "domain", "subdomain", "difficulty",
                      "estimated_time_min", "primary_skill"):
            assert item[field] == data[field], f"{item['id']}: {field} mismatch"


def test_index_file_paths_exist_and_match():
    problems = load_problems()
    for item in load_index_yaml()["items"]:
        file_path = ROOT / item["file_path"]
        assert file_path.exists(), f"{item['id']}: {item['file_path']} does not exist"
        assert file_path.resolve() == problems[item["id"]]["path"].resolve()


def test_index_csv_matches_disk():
    problems = load_problems()
    with (DATA_ROOT / "index.csv").open("r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        assert reader.fieldnames == INDEX_FIELDS
        rows = list(reader)
    csv_ids = {row["id"] for row in rows}
    assert csv_ids == set(problems), (
        "index.csv out of sync with on-disk YAML files; "
        "run scripts/generate_dataset.py"
    )
    assert len(rows) == len(csv_ids)


def test_layer_counts_match_index_summary():
    index = load_index_yaml()
    counted: dict[str, int] = {}
    for item in index["items"]:
        counted[item["layer"]] = counted.get(item["layer"], 0) + 1
    assert index["by_layer"] == counted
